package main
import("fmt";"os";"math"; "github.com/shivang991/DashDevil2D/apps/server/configuration";"github.com/shivang991/DashDevil2D/apps/server/protocol";"github.com/shivang991/DashDevil2D/apps/server/simulation")
func main(){d,_:=os.ReadFile("../../packages/contracts/configuration/defaults.json"); ids:=[2]protocol.Identity{{RoomId:1,SeatSession:11,PairGeneration:1,Seat:0},{RoomId:1,SeatSession:22,PairGeneration:1,Seat:1}}
for _,raw:=range []string{`{}`,`{"gameplay":{"laneShiftDuration":0.170001,"laneSwitchCooldownDuration":0.131002}}`,`{"gameplay":{"startingRoadSpeed":100,"maxRoadSpeed":500,"speedGrowth":777}}`}{c,err:=configuration.Capture(d,"road-rage",[]byte(raw));if err!=nil{panic(err)}; a,_:=simulation.New(c,991,ids,1);b,_:=simulation.New(c,991,ids,1); in:=protocol.Input{Identity:ids[0],Round:protocol.Round{RoundId:1,InputGeneration:1},Sequence:1,Control:2,HeldMask:2};a.Submit(ids[0],in);b.Submit(ids[0],in); a.AdvanceTo(.9);for i:=1;i<=90;i++ {b.AdvanceTo(float64(i)/100)}; sa,sb:=a.Snapshot(),b.Snapshot(); if sa.Cars!=sb.Cars{fmt.Printf("SCHEDULE MISMATCH %s\n%+v\n%+v\n",raw,sa.Cars,sb.Cars)};if math.Abs(sa.Cars[0].Progress-sb.Cars[0].Progress)>1e-6{panic("progress")};fmt.Println("PASS schedule",raw,sa.Cars[0].Lateral)}
}
